/**
 * The Electron side of the launcher contract (2026-10-22). Each block reads a table under
 * `tests/fixtures/` that `tests/test_launch_contract.py` reads for `tit/launch.py` and `loader.sh`,
 * so the three launchers cannot drift:
 *
 * - `project_hash.json` (generated by `node dev/gen_project_hash_fixture.mjs`, an independent
 *   BigInt reference over UTF-16 code units): `hash8` / `computeProjectName`.
 * - `session_labels.json` (authored from DECISIONS 2026-10-22): `isToolboxContainer`.
 * - `user_config_dirs.json` (authored): `userConfigDir(platform, env, home)`.
 * - `launch_contract.json` (authored from `docker-compose.yml`): `buildStackEnv` interpolated into
 *   the repository's real compose file by `composeFile.ts`, as `stack.ts#prepareFresh` does.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { buildStackEnv, computeProjectName, hash8, stackLabels } from "../../src/shared/compose";
import { buildContainerPlan, parseComposeFile } from "../../src/shared/composeFile";
import { projectDirName } from "../../src/shared/paths";
import { isToolboxContainer } from "../../src/main/stack";
import { userConfigDir } from "../../src/main/userConfig";

function fixture<T>(name: string): T {
  return JSON.parse(readFileSync(new URL(`../../../tests/fixtures/${name}`, import.meta.url), "utf-8")) as T;
}

interface HashRow { label: string; path: string; name: string }
interface SessionRow { label: string; labels: Record<string, string>; session: boolean }
interface ConfigRow { label: string; platform: NodeJS.Platform; home: string; XDG_CONFIG_HOME?: string; APPDATA?: string; expected: string }
type PerLeg = string | { python: string; ts: string };
interface ContractCase {
  label: string;
  input: {
    host_project_dir: string; port: number; token: string; user_config: string; timezone: string; no_telemetry: string;
    host_os: PerLeg; host_os_version: string; host_arch: string; repo_dir: string; static_dir: string; server_reload: boolean;
  };
  expected: { container_name: string; labels: Record<string, string>; environment: Record<string, PerLeg>; volumes: string[]; publish: string };
}

const hashRows = fixture<{ rows: HashRow[] }>("project_hash.json").rows;
const sessionRows = fixture<{ rows: SessionRow[] }>("session_labels.json").rows;
const configRows = fixture<{ rows: ConfigRow[] }>("user_config_dirs.json").rows;
const contract = fixture<{ cases: ContractCase[] }>("launch_contract.json").cases;
const ts = (value: PerLeg): string => (typeof value === "string" ? value : value.ts);

describe("shared launcher tables", () => {
  it("have rows to check", () => {
    expect(hashRows.length).toBeGreaterThanOrEqual(10);
    expect(hashRows.some((row) => [...row.path].some((ch) => ch.codePointAt(0)! > 0xffff))).toBe(true);
    expect(new Set(sessionRows.map((row) => row.session))).toEqual(new Set([true, false]));
    expect(new Set(configRows.map((row) => row.platform))).toEqual(new Set(["linux", "darwin", "win32"]));
    expect(contract.length).toBeGreaterThanOrEqual(3);
  });
});

describe("project identity (project_hash.json)", () => {
  it.each(hashRows.map((row) => [row.label, row] as const))("%s", (_label, row) => {
    expect(computeProjectName(row.path)).toBe(row.name);
    expect(`ti-toolbox-${hash8(row.path)}`).toBe(row.name);
  });
});

describe("session discovery (session_labels.json)", () => {
  it.each(sessionRows.map((row) => [row.label, row] as const))("%s", (_label, row) => {
    const container = { Id: "c", Names: ["/c"], Image: "idossha/ti-toolbox:v3.1.1", State: "running", Status: "Up", Labels: row.labels };
    expect(isToolboxContainer(container)).toBe(row.session);
  });
});

describe("user config dir (user_config_dirs.json)", () => {
  it.each(configRows.map((row) => [row.label, row] as const))("%s", (_label, row) => {
    const env: NodeJS.ProcessEnv = {};
    if (row.XDG_CONFIG_HOME !== undefined) env.XDG_CONFIG_HOME = row.XDG_CONFIG_HOME;
    if (row.APPDATA !== undefined) env.APPDATA = row.APPDATA;
    expect(userConfigDir(row.platform, env, row.home)).toBe(row.expected);
  });
});

describe("one container definition (launch_contract.json)", () => {
  const composeText = readFileSync(new URL("../../../docker-compose.yml", import.meta.url), "utf-8");

  it.each(contract.map((c) => [c.label, c] as const))("%s", (_label, c) => {
    const given = c.input;
    const env = buildStackEnv({
      hostProjectDir: given.host_project_dir,
      projectDirName: projectDirName(given.host_project_dir),
      userConfigDir: given.user_config,
      port: given.port,
      token: given.token,
      timezone: given.timezone,
      hostOs: ts(given.host_os),
      hostOsVersion: given.host_os_version,
      hostArch: given.host_arch,
      repoDir: given.repo_dir,
      serverReload: given.server_reload,
      ...(given.static_dir ? { staticDir: given.static_dir } : {}),
    });
    // stack.ts interpolates from `{...process.env, ...buildStackEnv(...)}`: the user's own
    // TIT_NO_TELEMETRY comes from the process environment, never from buildStackEnv.
    const stack = parseComposeFile(composeText, { TIT_NO_TELEMETRY: given.no_telemetry, ...env });
    const projectName = computeProjectName(given.host_project_dir);
    const plan = buildContainerPlan(stack, { serviceName: "tit", projectName, labels: stackLabels(given.host_project_dir) });

    expect(plan.containerName).toBe(c.expected.container_name);
    expect(plan.body.Labels).toEqual(c.expected.labels);
    const environment = Object.fromEntries(plan.body.Env.map((pair) => [pair.slice(0, pair.indexOf("=")), pair.slice(pair.indexOf("=") + 1)]));
    expect(environment).toEqual(Object.fromEntries(Object.entries(c.expected.environment).map(([k, v]) => [k, ts(v)])));
    expect(plan.body.HostConfig.Binds).toEqual(c.expected.volumes);
    const [binding] = Object.values(plan.body.HostConfig.PortBindings)[0] ?? [];
    expect(`${binding?.HostIp}:${binding?.HostPort}:${plan.containerPort}`).toBe(c.expected.publish);
  });
});
